mapper.sql:
r.content IS NOT NULL
  AND (
        r.reviewed_at <= #{cutoff}
        OR (
            r.reviewed_at IS NULL
            AND EXISTS (
                SELECT 1
                FROM memory t
                WHERE t.id = r.memory_id
                  AND t.status = 'HIDDEN'
                  AND t.updated_at <= #{cutoff}
            )
        )
      )
